/* Rebuild the static registry from the exact official package arrays retained here.
   No network, runtime package or framework dependency is needed. */
import fs from 'node:fs';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const directory=path.dirname(fileURLToPath(import.meta.url));
const read=name=>JSON.parse(fs.readFileSync(path.join(directory,name),'utf8'));
const definitions=read('definitions.json'),mapping=read('mapping.json'),source=read('source.json');
const escape=value=>String(value).replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const attrName=name=>name.replace(/[A-Z]/g,char=>'-'+char.toLowerCase());
const drawable=new Set(['path','circle','ellipse','rect','line','polyline','polygon']);
const assets={};
for(const name of new Set(Object.values(mapping))){
 const nodes=definitions[name];if(!nodes?.length)throw new Error('Missing official definition: '+name);
 assets[name]=nodes.map(([tag,attributes])=>{
  if(!drawable.has(tag))throw new Error('Unexpected source element '+tag);
  // Coordinates and geometry are unchanged. Source presentation defaults are
  // inherited from the shared wrapper so stroke width stays in CSS pixels.
  const attrs=Object.entries(attributes).filter(([key])=>!['key','strokeWidth','strokeLinecap','strokeLinejoin'].includes(key)).map(([key,value])=>`${attrName(key)}="${escape(value)}"`).join(' ');
  return `<${tag} ${attrs} vector-effect="non-scaling-stroke"/>`;
 }).join('');
}
const code=`/* Hugeicons ${source.style} — official ${source.package}@${source.version}.
 * Geometry: vendor/hugeicons/definitions.json; mapping/provenance/license alongside.
 * Generated by node vendor/hugeicons/build.mjs. No runtime dependency.
 */
(function(F){
 'use strict';
 const assets=${JSON.stringify(assets,null,2)};
 const mapping=${JSON.stringify(mapping,null,2)};
 const icons=Object.freeze(Object.fromEntries(Object.entries(mapping).map(([key,name])=>[key,Object.freeze({name,markup:assets[name]})])));
 F.icons=icons;
 F.hugeicons=icons;
 const numericToken=(id,fallback)=>{const value=Number.parseFloat(F.resolve?.(id));return Number.isFinite(value)&&value>0?value:fallback;};
 const dimension=size=>Number.isFinite(Number(size))&&Number(size)>0?Number(size):16;
 F.iconStroke=(size=16)=>dimension(size)<=numericToken('icon.size.threshold',16)?numericToken('icon.stroke.small',1.25):numericToken('icon.stroke.large',1.5);
 F.icon=(name,size=16)=>{
  const icon=Object.hasOwn(icons,name)?icons[name]:null;
  if(!icon)throw new RangeError('Unknown Hugeicons semantic key: '+String(name));
  const renderedSize=dimension(size),stroke=F.iconStroke(renderedSize);
  return \`<svg class="hugeicon" data-hugeicon="\${icon.name}" width="\${renderedSize}" height="\${renderedSize}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="\${stroke}" stroke-linecap="round" stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">\${icon.markup}</svg>\`;
 };
})(window.Forma);
`;
const output=path.resolve(directory,'../../dist/hugeicons-icons.js');
if(process.argv.includes('--check')){if(fs.readFileSync(output,'utf8')!==code)throw new Error('Hugeicons registry is stale');console.log('Hugeicons registry matches official vendored definitions and semantic mappings.');}
else{fs.writeFileSync(output,code);console.log(`Built ${Object.keys(mapping).length} semantic keys from ${Object.keys(assets).length} official Hugeicons Stroke Rounded assets.`);}
